import os
import requests

def redact_unsafe(payload, config=None):
    config = config or {}
    api_key = os.getenv("PERSPECTIVE_API_KEY") or config.get("api_key")
    url = "https://commentanalyzer.googleapis.com/v1alpha1/comments:analyze"
    data = {
        "comment": {"text": payload},
        "languages": ["en"],
        "requestedAttributes": {
            "TOXICITY": {},
            "SEVERE_TOXICITY": {},
            "IDENTITY_ATTACK": {},
            "INSULT": {},
            "PROFANITY": {},
            "THREAT": {}
        },
        "doNotStore": True
    }
    params = {"key": api_key}
    response = requests.post(url, json=data, params=params)
    response.raise_for_status()
    analysis = response.json()

    spans = []
    for attribute, details in analysis.get("attributeScores", {}).items():
        if details["summaryScore"]["value"] > (config.get("threshold", 0.7)):
            spans.append({
                "start": 0,
                "end": len(payload),
                "severity": attribute.lower(),
                "message": f"Flagged for {attribute.lower()}"
            })

    # Simple redaction by replacing the entire text if unsafe
    if spans:
        return {
            "redacted_text": "[REDACTED]",
            "spans": spans
        }
    return {
        "redacted_text": payload,
        "spans": []
    }
